window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f804151a08e62a9c"]={"versions": [{"id": "FIG-f804151a08e62a9c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR VFB-/Komponentendiagramm (Port-Verbindungsmuster). Dargestellt ist der strukturelle Ausschnitt einer Client-Server-Verbindung zwischen einer AUTOSAR Software-Component (SW-C) und dem Development Error Tracer (DET) über standardisierte Service-Ports auf Ebene des Virtual Function Bus (VFB) bzw. der RTE.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten / Partitionen</strong>: Links Rand einer Client-Software-Component (SW-C), rechts Rand der BSW-Service-Komponente (DET).</li>\n<li><strong>Ports</strong>: Quadratische Port-Begrenzungssymbole an den Komponentengrenzen.</li>\n<li><strong>Port-Schnittstellentypen</strong>:</li>\n<li>Required Port (R-Port) auf SW-C-Seite, visualisiert durch ein Socket-/Halbkreissymbol (Client-Rolle).</li>\n<li>Provided Port (P-Port) auf DET-Seite, visualisiert durch ein Ball-/Lollipop-Symbol (Server-Rolle).</li>\n<li><strong>Konnektor</strong>: Horizontale Verbindungslinie (Assembly Connector) zwischen Socket und Ball zur Abbildung des Service-Interface-Funktionsaufrufs (z. B. DET-Fehlermeldeoperation).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Konnektordiagramm ohne dynamische Ablauf- oder Zustandssequenzen. Impliziert wird ein synchroner/asynchroner Client-Server-Aufruf: Eine SW-C-Funktion ruft über die RTE den BSW-Service des DET auf; die RTE leitet die Parameter (<code>ModuleId</code>, <code>InstanceId</code>, <code>ApiId</code>, <code>ErrorId</code>) an den P-Port des DET weiter und liefert den Status (<code>Std_ReturnType</code>, typischerweise <code>E_OK</code>) an die SW-C zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht die normative Anbindung von SW-Cs an die BSW-Dienste des DET über Client-Server-Interfaces und RTE-Service-Ports.</li>\n<li>Für mehrfach instanziierte Software-Komponenten können spezifische Ports bzw. <code>PortDefinedArgumentValues</code> verwendet werden, um die Identifikation (z. B. Abbildung auf unterschiedliche <code>ModuleId</code>s) in der RTE zu gewährleisten.</li>\n<li>Entwickler müssen die interne Fehler- und API-Semantik (<code>InstanceId</code>, <code>ApiId</code>, <code>ErrorId</code>) SW-C-spezifisch definieren, da oberhalb der RTE keine Standardisierung dieser IDs existiert.</li>\n</ul>"}, {"id": "FIG-99b2dcf7686066e6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR VFB-/Komponentendiagramm (Port-Verbindungsmuster). Dargestellt ist der strukturelle Ausschnitt einer Client-Server-Verbindung zwischen einer AUTOSAR Software-Component (SW-C) und dem Development Error Tracer (DET) über standardisierte Service-Ports auf Ebene des Virtual Function Bus (VFB) bzw. der RTE.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Komponenten / Partitionen</strong>: Links Rand einer Client-Software-Component (SW-C), rechts Rand der BSW-Service-Komponente (DET).</li>\n<li><strong>Ports</strong>: Quadratische Port-Begrenzungssymbole an den Komponentengrenzen.</li>\n<li><strong>Port-Schnittstellentypen</strong>:</li>\n<li>Required Port (R-Port) auf SW-C-Seite, visualisiert durch ein Socket-/Halbkreissymbol (Client-Rolle).</li>\n<li>Provided Port (P-Port) auf DET-Seite, visualisiert durch ein Ball-/Lollipop-Symbol (Server-Rolle).</li>\n<li><strong>Konnektor</strong>: Horizontale Verbindungslinie (Assembly Connector) zwischen Socket und Ball zur Abbildung des Service-Interface-Funktionsaufrufs (z. B. DET-Fehlermeldeoperation).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Konnektordiagramm ohne dynamische Ablauf- oder Zustandssequenzen. Impliziert wird ein synchroner/asynchroner Client-Server-Aufruf: Eine SW-C-Funktion ruft über die RTE den BSW-Service des DET auf; die RTE leitet die Parameter (<code>ModuleId</code>, <code>InstanceId</code>, <code>ApiId</code>, <code>ErrorId</code>) an den P-Port des DET weiter und liefert den Status (<code>Std_ReturnType</code>, typischerweise <code>E_OK</code>) an die SW-C zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Veranschaulicht die normative Anbindung von SW-Cs an die BSW-Dienste des DET über Client-Server-Interfaces und RTE-Service-Ports.</li>\n<li>Für mehrfach instanziierte Software-Komponenten können spezifische Ports bzw. <code>PortDefinedArgumentValues</code> verwendet werden, um die Identifikation (z. B. Abbildung auf unterschiedliche <code>ModuleId</code>s) in der RTE zu gewährleisten.</li>\n<li>Entwickler müssen die interne Fehler- und API-Semantik (<code>InstanceId</code>, <code>ApiId</code>, <code>ErrorId</code>) SW-C-spezifisch definieren, da oberhalb der RTE keine Standardisierung dieser IDs existiert.</li>\n</ul>"}], "trans": [{"from": "FIG-f804151a08e62a9c", "to": "FIG-99b2dcf7686066e6", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
